import React, { useMemo } from 'react';
import clsx from 'clsx';
import {
  type ChannelPreviewDeliveryStatus,
  type ChannelPreviewMessageType,
  useLatestMessagePreview,
  type UseLatestMessagePreviewParams,
} from './hooks/useLatestMessagePreview';
import { getPlainPreviewText } from './previewText';
import {
  useChatContext,
  useComponentContextIcons,
  useTranslationContext,
} from '../../context';

/** Props of {@link SummarizedMessagePreview} and of a `ComponentContext` override of it. */
export type SummarizedMessagePreviewProps = UseLatestMessagePreviewParams;

export const SummarizedMessagePreview = ({
  latestMessage,
  messageDeliveryStatus,
  participantCount,
}: UseLatestMessagePreviewParams) => {
  const {
    IconCamera,
    IconCheckmark1Small,
    IconChecks,
    IconClock,
    IconExclamationCircleFill,
    IconFile,
    IconGiphy,
    IconLink,
    IconLocation,
    IconNoSign,
    IconUnsupportedAttachment,
    IconVideo,
    IconVoice,
  } = useComponentContextIcons();
  const { isMessageAIGenerated } = useChatContext();
  const { userLanguage } = useTranslationContext();

  const deliveryStatusIconMap: Record<ChannelPreviewDeliveryStatus, React.ComponentType> =
    {
      delivered: IconChecks,
      read: IconChecks,
      sending: IconClock,
      sent: IconCheckmark1Small,
    };

  const contentTypeIconMap: Partial<
    Record<ChannelPreviewMessageType, React.ComponentType>
  > = {
    deleted: IconNoSign,
    error: IconExclamationCircleFill,
    file: IconFile,
    giphy: IconGiphy,
    image: IconCamera,
    link: IconLink,
    location: IconLocation,
    unsupported: IconUnsupportedAttachment,
    video: IconVideo,
    voice: IconVoice,
  };

  const { deliveryStatus, senderName, text, type } = useLatestMessagePreview({
    latestMessage,
    messageDeliveryStatus,
    participantCount,
  });
  // The preview is a single line of plain text: the message text shows without inline markdown
  // syntax, while lists and tables keep their markers.
  const plainText = useMemo(
    () =>
      getPlainPreviewText({
        format: 'display',
        isMessageAIGenerated,
        latestMessage,
        text,
        type,
        userLanguage,
      }),
    [isMessageAIGenerated, latestMessage, text, type, userLanguage],
  );

  const DeliveryStatusIcon = deliveryStatus
    ? deliveryStatusIconMap[deliveryStatus]
    : undefined;
  const ContentTypeIcon = contentTypeIconMap[type];

  return (
    <div
      className={clsx('str-chat__summarized-message-preview', {
        [`str-chat__summarized-message-preview--${type}`]: type,
      })}
    >
      {type !== 'error' && (
        <>
          {DeliveryStatusIcon && (
            <span
              className={clsx('str-chat__summarized-message-preview__delivery-status', {
                [`str-chat__summarized-message-preview__delivery-status--${deliveryStatus}`]:
                  deliveryStatus,
              })}
            >
              <DeliveryStatusIcon />
            </span>
          )}
          {senderName && (
            <span className='str-chat__summarized-message-preview__sender'>
              {senderName}:
            </span>
          )}
        </>
      )}
      {ContentTypeIcon && <ContentTypeIcon />}
      <span className='str-chat__summarized-message-preview__text'>{plainText}</span>
    </div>
  );
};
